// REQ-162 (docs/sims.md 4.1, 4.3, 20): typed command patterns, the small log
// search grammar and the IP/CIDR helpers. Everything here is a tokenizer or
// integer arithmetic; there is no regex, so no backtracking and no host
// behaviour to differ between engines.

import type { RecordValue, Value } from "./types.ts";

// ---- IPv4 / CIDR, integer arithmetic only (division and remainder by powers of two) ----

const POW2: number[] = [];
for (let i = 0, v = 1; i <= 32; i++, v *= 2) POW2.push(v);

export function parseIpv4(s: string): number | null {
  const parts = s.split(".");
  if (parts.length !== 4) return null;
  let v = 0;
  for (const p of parts) {
    if (p.length === 0 || p.length > 3) return null;
    for (let i = 0; i < p.length; i++) if (p[i] < "0" || p[i] > "9") return null;
    if (p.length > 1 && p[0] === "0") return null; // no leading zeros
    const n = Number(p);
    if (n > 255) return null;
    v = v * 256 + n;
  }
  return v;
}

export function parseCidr(s: string): { ip: number; prefix: number } | null {
  const slash = s.indexOf("/");
  if (slash < 0) return null;
  const ip = parseIpv4(s.slice(0, slash));
  const p = s.slice(slash + 1);
  if (ip === null || p.length === 0 || p.length > 2) return null;
  for (let i = 0; i < p.length; i++) if (p[i] < "0" || p[i] > "9") return null;
  if (p.length > 1 && p[0] === "0") return null;
  const prefix = Number(p);
  if (prefix > 32) return null;
  return { ip, prefix };
}

export function ipToInt(s: string): number {
  const v = parseIpv4(s);
  return v === null ? -1 : v;
}

// network address: clear the host bits by dividing out and multiplying back
export function networkOf(ip: number, prefix: number): number {
  const hostSize = POW2[32 - prefix];
  return (ip - (ip % hostSize));
}

export function intToIp(v: number): string {
  const a = Math.floor(v / 16777216) % 256;
  const b = Math.floor(v / 65536) % 256;
  const c = Math.floor(v / 256) % 256;
  const d = v % 256;
  return `${a}.${b}.${c}.${d}`;
}

export function ipInCidr(ip: string, cidr: string): boolean {
  const i = parseIpv4(ip);
  const c = parseCidr(cidr);
  if (i === null || c === null) return false;
  return networkOf(i, c.prefix) === networkOf(c.ip, c.prefix);
}

export function cidrContains(a: string, b: string): boolean {
  const ca = parseCidr(a);
  const cb = parseCidr(b);
  if (!ca || !cb || cb.prefix < ca.prefix) return false;
  return networkOf(cb.ip, ca.prefix) === networkOf(ca.ip, ca.prefix);
}

export function sameSubnet(a: string, b: string, prefix: number): boolean {
  const ia = parseIpv4(a);
  const ib = parseIpv4(b);
  if (ia === null || ib === null || prefix < 0 || prefix > 32 || prefix !== Math.floor(prefix)) return false;
  return networkOf(ia, prefix) === networkOf(ib, prefix);
}

export function cidrPrefix(c: string): number {
  const p = parseCidr(c);
  return p ? p.prefix : -1;
}

export function cidrNetwork(c: string): string {
  const p = parseCidr(c);
  return p ? `${intToIp(networkOf(p.ip, p.prefix))}/${p.prefix}` : "";
}

// ---- command patterns (4.1) ----

export type CaptureType = "word" | "int" | "ipv4" | "cidr" | { enum: string[] };

export type PatternToken = { lit: string } | { capture: string; type: CaptureType };

// Whitespace split and small character tests by hand: this folder uses no
// regular expressions (docs/sims.md 15), so nothing here can backtrack.
export function splitWs(s: string): string[] {
  const out: string[] = [];
  let cur = "";
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (c === " " || c === "\t" || c === "\n" || c === "\r") {
      if (cur) out.push(cur);
      cur = "";
    } else cur += c;
  }
  if (cur) out.push(cur);
  return out;
}

function isLower(c: string): boolean {
  return c >= "a" && c <= "z";
}
function isAlnumUnderscore(c: string): boolean {
  return (c >= "a" && c <= "z") || (c >= "A" && c <= "Z") || (c >= "0" && c <= "9") || c === "_";
}
export function isIdent(s: string): boolean {
  if (!s.length || !isLower(s[0])) return false;
  for (let i = 1; i < s.length; i++) if (!isAlnumUnderscore(s[i])) return false;
  return true;
}
function isIntText(s: string): boolean {
  let i = 0;
  if (s[0] === "-") i = 1;
  const digits = s.length - i;
  if (digits < 1 || digits > 10) return false;
  for (; i < s.length; i++) if (s[i] < "0" || s[i] > "9") return false;
  return true;
}

export function parsePattern(pattern: string): PatternToken[] | string {
  const out: PatternToken[] = [];
  for (const tok of splitWs(pattern)) {
    if (tok === "") continue;
    if (tok[0] === "{") {
      if (tok[tok.length - 1] !== "}") return `capture "${tok}" is not closed`;
      const inner = tok.slice(1, -1);
      const colon = inner.indexOf(":");
      if (colon < 0) return `capture "${tok}" needs a type (word, int, ipv4, cidr or enum(a|b))`;
      const name = inner.slice(0, colon);
      const ty = inner.slice(colon + 1);
      if (!isIdent(name)) return `capture name "${name}" is not an id`;
      if (ty === "word" || ty === "int" || ty === "ipv4" || ty === "cidr") out.push({ capture: name, type: ty });
      else if (ty.startsWith("enum(") && ty.endsWith(")")) {
        const values = ty.slice(5, -1).split("|").filter((v) => v.length > 0);
        if (!values.length) return `capture "${name}" has an empty enum`;
        out.push({ capture: name, type: { enum: values } });
      } else return `capture "${name}" has unknown type "${ty}"`;
    } else out.push({ lit: tok });
  }
  if (!out.length) return "pattern is empty";
  return out;
}

export function captureTypeName(t: CaptureType): string {
  return typeof t === "string" ? t : `enum(${t.enum.join("|")})`;
}

const WORD_OK = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789._:/-";

function wordOk(s: string): boolean {
  if (s.length < 1 || s.length > 64) return false;
  for (let i = 0; i < s.length; i++) if (WORD_OK.indexOf(s[i]) < 0) return false;
  return true;
}

export function commandInputOk(input: string): boolean {
  if (input.length > 200) return false;
  for (let i = 0; i < input.length; i++) {
    const c = input.charCodeAt(i);
    if (c < 32 || c === 127) return false;
  }
  return true;
}

export function splitCommand(input: string): string[] {
  return splitWs(input);
}

// Returns the bound captures, or null when the pattern does not match.
export function matchPattern(tokens: PatternToken[], words: string[]): Record<string, Value> | null {
  if (tokens.length !== words.length) return null;
  const out: Record<string, Value> = {};
  for (let i = 0; i < tokens.length; i++) {
    const t = tokens[i];
    const w = words[i];
    if ("lit" in t) {
      if (t.lit.toLowerCase() !== w.toLowerCase()) return null;
      continue;
    }
    const ty = t.type;
    if (ty === "word") {
      if (!wordOk(w)) return null;
      out[t.capture] = w;
    } else if (ty === "int") {
      if (!isIntText(w)) return null;
      const v = Number(w);
      if (v > 2147483648 || v < -2147483648) return null;
      out[t.capture] = v;
    } else if (ty === "ipv4") {
      if (parseIpv4(w) === null) return null;
      out[t.capture] = w;
    } else if (ty === "cidr") {
      if (parseCidr(w) === null) return null;
      out[t.capture] = w;
    } else {
      const hit = ty.enum.find((v) => v.toLowerCase() === w.toLowerCase());
      if (hit === undefined) return null;
      out[t.capture] = hit;
    }
  }
  return out;
}

// ---- log search grammar (20): terms, field:value, AND / OR / NOT, trailing * ----

type QNode =
  | { k: "term"; field: string | null; value: string; prefix: boolean }
  | { k: "and"; a: QNode; b: QNode }
  | { k: "or"; a: QNode; b: QNode }
  | { k: "not"; a: QNode };

function qTokens(q: string): string[] {
  return splitWs(q);
}

export function parseQuery(q: string): QNode | null {
  const toks = qTokens(q.slice(0, 200));
  let p = 0;
  const term = (): QNode | null => {
    if (p >= toks.length) return null;
    const t = toks[p];
    if (t.toUpperCase() === "NOT") {
      p++;
      const inner = term();
      return inner ? { k: "not", a: inner } : null;
    }
    if (t.toUpperCase() === "AND" || t.toUpperCase() === "OR") return null;
    p++;
    const colon = t.indexOf(":");
    let field: string | null = null;
    let value = t;
    if (colon > 0) {
      field = t.slice(0, colon);
      value = t.slice(colon + 1);
    }
    const prefix = value.endsWith("*");
    if (prefix) value = value.slice(0, -1);
    return { k: "term", field, value: value.toLowerCase(), prefix };
  };
  const andExpr = (): QNode | null => {
    let left = term();
    if (!left) return null;
    for (;;) {
      if (p < toks.length && toks[p].toUpperCase() === "AND") {
        p++;
        const r = term();
        if (!r) return null;
        left = { k: "and", a: left, b: r };
      } else if (p < toks.length && toks[p].toUpperCase() !== "OR") {
        const r = term(); // implicit AND between bare terms
        if (!r) return null;
        left = { k: "and", a: left, b: r };
      } else return left;
    }
  };
  let left = andExpr();
  if (!left) return null;
  while (p < toks.length && toks[p].toUpperCase() === "OR") {
    p++;
    const r = andExpr();
    if (!r) return null;
    left = { k: "or", a: left, b: r };
  }
  return p >= toks.length ? left : null;
}

function fieldText(v: unknown): string {
  if (v === null || v === undefined) return "";
  if (typeof v === "string") return v.toLowerCase();
  if (typeof v === "number" || typeof v === "boolean") return String(v).toLowerCase();
  if (Array.isArray(v)) return v.map((x) => fieldText(x)).join(" ");
  return "";
}

function termMatches(node: { field: string | null; value: string; prefix: boolean }, rec: RecordValue, fields: string[]): boolean {
  if (node.value === "") return true;
  const names = node.field ? (fields.indexOf(node.field) >= 0 ? [node.field] : []) : fields;
  for (const f of names) {
    const text = fieldText(rec[f]);
    if (node.prefix) {
      for (const word of text.split(" ")) if (word.startsWith(node.value)) return true;
      if (text.startsWith(node.value)) return true;
    } else if (node.field) {
      if (text === node.value || text.split(" ").indexOf(node.value) >= 0) return true;
    } else if (text.split(" ").indexOf(node.value) >= 0 || text === node.value) return true;
  }
  return false;
}

export function matchQuery(rec: RecordValue, q: string, fields: string[]): boolean {
  const ast = parseQuery(q);
  if (!ast) return false;
  const ev = (n: QNode): boolean => {
    switch (n.k) {
      case "term":
        return termMatches(n, rec, fields);
      case "and":
        return ev(n.a) && ev(n.b);
      case "or":
        return ev(n.a) || ev(n.b);
      case "not":
        return !ev(n.a);
    }
  };
  return ev(ast);
}
